	// 购买时刻接近可表示上限时，普通天数也可能不可表示。
	far := time.Unix(math.MaxInt64-62135596800-100, 0).UTC()
	if err := s.RegisterProduct("q", far, 2, nil); !errors.Is(err, ErrInvalidParam) {
		t.Fatalf("near-limit purchase: got %v, want ErrInvalidParam", err)
	}
}

// 首次预留与资格查询使用一致的截止时刻：截止前可预留，截止时刻起返回
// 不合格错误，不创建承诺、不占用备件，历史中的资格依据显示正确的
// 购买时刻、原保修天数和截止时刻。
func TestLongWarrantyReserveBoundary(t *testing.T) {
	purchase := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	s := NewStore()
	if err := s.RegisterProduct("p", purchase, 106752, nil); err != nil {
		t.Fatal(err)
	}
	if err := s.RegisterPart("sp", 10); err != nil {
		t.Fatal(err)
	}
	if err := s.SubmitRequest("r", "p", "F1"); err != nil {
		t.Fatal(err)
	}
	elig, err := s.Evaluate("r", purchase)
	if err != nil {
		t.Fatal(err)
	}
	expiry := elig.WarrantyExpiry
	// 承诺自身的到期时刻只需晚于本次提交的当前时刻，与保修截止时刻各自独立。
	commitExpiry := expiry.Add(24 * time.Hour)

	// 截止时刻前一秒：预留成功。
	if _, err := s.Reserve("c1", "r", "sp", 1, commitExpiry, expiry.Add(-time.Second)); err != nil {
		t.Fatalf("reserve before warranty expiry: %v", err)
	}
	// 截止时刻：不合格，不创建承诺、不占用备件。
	if _, err := s.Reserve("c2", "r", "sp", 1, commitExpiry, expiry); !errors.Is(err, ErrIneligible) {
		t.Fatalf("reserve at warranty expiry: got %v, want ErrIneligible", err)
	}
	if _, err := s.Commitment("c2"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("rejected reserve must not create a commitment, got %v", err)
	}
	st, err := s.PartStatus("sp", expiry)
	if err != nil {
		t.Fatal(err)
	}
	if st.ActiveOccupied != 1 {
		t.Fatalf("occupied = %d, want 1 (only the successful reserve)", st.ActiveOccupied)
	}

	hist, err := s.RequestHistory("r")
	if err != nil {
		t.Fatal(err)
	}
	if len(hist) != 2 || !hist[0].Success || hist[1].Success || hist[1].Error != HistoryErrorIneligible {
		t.Fatalf("unexpected history: %+v", hist)
	}
	basis := hist[1].Eligibility
	if basis == nil {
		t.Fatal("rejected record missing eligibility basis")
	}
	if !basis.PurchaseTime.Equal(purchase) || basis.WarrantyDays != 106752 || !basis.WarrantyExpiry.Equal(expiry) {
		t.Fatalf("basis = (%v, %d, %v), want (%v, 106752, %v)",
			basis.PurchaseTime, basis.WarrantyDays, basis.WarrantyExpiry, purchase, expiry)
	}
	if !containsReason(basis.Reasons, ReasonWarrantyExpired) {
		t.Fatalf("rejection reasons %v missing warranty_expired", basis.Reasons)
	}
}

// 较长期限不能绕过其他拒绝条件：购买时刻在未来、故障代码命中除外清单
// 仍各自构成拒绝原因，过保与除外同时成立时保留两项原因。
func TestLongWarrantyOtherRejectionReasons(t *testing.T) {
	purchase := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	s := NewStore()
	if err := s.RegisterProduct("p", purchase, 106752, []string{"FX"}); err != nil {
		t.Fatal(err)
	}
	if err := s.SubmitRequest("r", "p", "FX"); err != nil {
		t.Fatal(err)
	}
	// 购买时刻晚于当前时刻。
	e, err := s.Evaluate("r", purchase.Add(-time.Second))
	if err != nil {
		t.Fatal(err)
	}
	if e.Eligible || !containsReason(e.Reasons, ReasonPurchaseInFuture) {
		t.Fatalf("future purchase: %+v", e)
	}
	// 除外故障代码。
	e, err = s.Evaluate("r", purchase)
	if err != nil {
		t.Fatal(err)
	}
	if e.Eligible || !containsReason(e.Reasons, ReasonFaultExcluded) {
		t.Fatalf("excluded fault: %+v", e)
	}
	// 过保与除外同时成立时保留两项原因。
	e, err = s.Evaluate("r", e.WarrantyExpiry)
	if err != nil {
		t.Fatal(err)
	}
	if e.Eligible || !containsReason(e.Reasons, ReasonWarrantyExpired) || !containsReason(e.Reasons, ReasonFaultExcluded) {
		t.Fatalf("expired+excluded: %+v", e)
	}
}

func containsReason(rs []RejectionReason, want RejectionReason) bool {
	for _, r := range rs {
		if r == want {
			return true
		}
	}
	return false
}

package warranty

import (
	"fmt"
	"time"
)

// HistoryError 是预留提交失败的具体错误类别。
type HistoryError string

const (
	// HistoryErrorInvalidParam 表示入参不合法（如非正数量、到期时刻未晚于当前时刻）。
	HistoryErrorInvalidParam HistoryError = "invalid_param"
	// HistoryErrorConflict 表示提交编号被重复用于不同内容。
	HistoryErrorConflict HistoryError = "conflict"
	// HistoryErrorProductNotFound 表示请求关联的产品尚未登记，资格依据为空。
	HistoryErrorProductNotFound HistoryError = "product_not_found"
	// HistoryErrorPartNotFound 表示预留的备件尚未登记，库存依据为空。
	HistoryErrorPartNotFound HistoryError = "part_not_found"
	// HistoryErrorIneligible 表示请求在当次时刻不满足保修资格。
	HistoryErrorIneligible HistoryError = "ineligible"
	// HistoryErrorInsufficientStock 表示可承诺数量不足。
	HistoryErrorInsufficientStock HistoryError = "insufficient_stock"
)

// StockBasis 是提交处理前的库存依据快照。
type StockBasis struct {
	// PhysicalRemaining 是本次提交处理前的剩余实物库存。
	PhysicalRemaining int
	// ActiveOccupied 是本次提交处理前的有效承诺未用总量。
	ActiveOccupied int
	// Committable 是本次提交处理前的可承诺数量（实物剩余扣除有效占用）。
	Committable int
}

// HistoryRecord 是一次预留提交的处理历史记录。
// 每次首次预留成功及每次失败提交都会留下一条记录；同编号同内容的幂等重试不追加。
type HistoryRecord struct {
	// Seq 是记录在所属请求内的处理次序号，按处理次序严格递增。
	Seq int
	// CommitID 是本次提交的承诺编号。
	CommitID string
	// PartID 是本次提交预留的备件编号。
	PartID string
	// Quantity 是本次提交的数量。
	Quantity int
	// Expiry 是本次提交的到期时刻。
	Expiry time.Time
	// Now 是调用方本次提交给定的当前时刻。
	Now time.Time
	// Success 表示本次提交是否成功。
	Success bool
	// Error 是失败的具体错误类别；成功时为空。
	Error HistoryError
	// Eligibility 是资格依据快照；产品缺失等情况下明确为空（nil），不用合格替代缺失。
	Eligibility *Eligibility
	// StockBasis 是库存依据快照；备件缺失等情况下明确为空（nil），不用零库存替代缺失。
	StockBasis *StockBasis
}

// cloneEligibility 返回资格依据快照的深拷贝（含拒绝原因列表）。
func cloneEligibility(e *Eligibility) *Eligibility {
	if e == nil {
		return nil
	}
	cp := *e
	if len(e.Reasons) > 0 {
		cp.Reasons = append(make([]RejectionReason, 0, len(e.Reasons)), e.Reasons...)
	}
	return &cp
}

// cloneStockBasis 返回库存依据快照的深拷贝。
func cloneStockBasis(b *StockBasis) *StockBasis {
	if b == nil {
		return nil
	}
	cp := *b
	return &cp
}

// appendHistoryLocked 在已持锁的情况下追加一条处理记录。
// 序号按处理次序严格递增；提交时刻相同或前后颠倒都不改变这个次序。
func (s *Store) appendHistoryLocked(requestID string, rec HistoryRecord) {
	rec.Seq = len(s.history[requestID]) + 1
	s.history[requestID] = append(s.history[requestID], rec)
}

// recordInvalidParamLocked 在已持锁的情况下，仅当请求已知时记录一次参数无效失败。
func (s *Store) recordInvalidParamLocked(requestID, commitID, partID string, quantity int, expiry, now time.Time) {
	if requestID == "" {
		return
	}
	if _, ok := s.requests[requestID]; !ok {
		return
	}
	s.appendHistoryLocked(requestID, HistoryRecord{
		CommitID: commitID,
		PartID:   partID,
		Quantity: quantity,
		Expiry:   expiry,
		Now:      now,
		Error:    HistoryErrorInvalidParam,
	})
}

// RequestHistory 返回指定请求的预留处理历史，按处理次序排列，序号严格递增。
// 历史查询不需要提供当前时刻；已知请求没有记录时返回空列表。
// 返回的列表及记录均为副本，调用方修改不会影响已保存的历史与后续查询。
func (s *Store) RequestHistory(requestID string) ([]HistoryRecord, error) {
	if requestID == "" {
		return nil, fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, ok := s.requests[requestID]; !ok {
		return nil, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
	}
	src := s.history[requestID]
	out := make([]HistoryRecord, len(src))
	for i, rec := range src {
		cp := rec
		cp.Eligibility = cloneEligibility(rec.Eligibility)
		cp.StockBasis = cloneStockBasis(rec.StockBasis)
		out[i] = cp
	}
	return out, nil
}

